function scriptToRows(sc) {
  return (sc.messages || []).map((m) => m.divider ? { sender: "divider", text: m.divider } : { sender: m.from === "astro" ? "astro" : "user", text: m.text });
}
function rowsToScript(rs) {
  return { messages: rs.filter((r) => (r.text || "").trim()).map((r) => r.sender === "divider" ? { divider: r.text } : (r.sender === "astro" ? { from: "astro", text: r.text, typing: true } : { from: "user", text: r.text })) };
}
function sysPrompt(lang) {
  return `You write short, authentic WhatsApp-style astrologer consultation chats for a marketing video (AstroChat). Output ONLY valid JSON, no markdown, no preamble. Schema: {"messages":[ {"from":"user"|"astro","text":"...","time":"hh:mm am/pm","typing":true} OR {"divider":"..."} ]}. Write ALL message text in ${lang}: use the natural script for that language (for Hinglish use Roman letters). 5 to 8 items. The user is emotional and seeking help (love, career, family, an ex). The astrologer is calm, warm, reassuring, says beti/beta, asks for date of birth, gives a hopeful specific prediction. You MAY include exactly ONE {"divider":"..."} time-jump near the end followed by a grateful user message. Put "typing":true on astrologer messages. Keep each text under 12 words.`;
}

